type publicationWhere[Q sqlite.Filterable] struct {
	cols        publicationColumns
	ID          sqlite.WhereMod[Q, string]
	CreatedAt   sqlite.WhereMod[Q, time.Time]
	Version     sqlite.WhereMod[Q, int64]
	PublishedBy sqlite.WhereMod[Q, string]
	Snapshot    sqlite.WhereMod[Q, types.JSON[json.RawMessage]]
	ItemID      sqlite.WhereMod[Q, string]
	Action      sqlite.WhereMod[Q, string]
	RevisionID  sqlite.WhereNullMod[Q, string]
	R           publicationWhereR[Q]
}

func (publicationWhere[Q]) AliasedAs(alias string) publicationWhere[Q] {
	return buildPublicationWhere[Q](buildPublicationColumns(alias))
}

func buildPublicationWhere[Q sqlite.Filterable](cols publicationColumns) publicationWhere[Q] {
	return publicationWhere[Q]{
		cols:        cols,
		ID:          sqlite.Where[Q, string](cols.ID.Expression),
		CreatedAt:   sqlite.Where[Q, time.Time](cols.CreatedAt.Expression),
		Version:     sqlite.Where[Q, int64](cols.Version.Expression),
		PublishedBy: sqlite.Where[Q, string](cols.PublishedBy.Expression),
		Snapshot:    sqlite.Where[Q, types.JSON[json.RawMessage]](cols.Snapshot.Expression),
		ItemID:      sqlite.Where[Q, string](cols.ItemID.Expression),
		Action:      sqlite.Where[Q, string](cols.Action.Expression),
		RevisionID:  sqlite.WhereNull[Q, string](cols.RevisionID.Expression),
		R:           publicationWhereR[Q]{cols: cols},
	}
}

// publicationWhereR holds the relationship-based filters of
// publicationWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type publicationWhereR[Q sqlite.Filterable] struct {
	cols publicationColumns
}

// HasRevisionItemRevision filters parents that have a matching RevisionItemRevision using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to ItemRevisions).
func (w publicationWhereR[Q]) HasRevisionItemRevision(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := sqlite.Select(
		sm.Columns(sqlite.Raw("1")),
		sm.From(ItemRevisions.NameExpr()),
		sm.Where(ItemRevisions.Columns.ID.EQ(w.cols.RevisionID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: sqlite.Exists(q)}
}

// HasItemResource filters parents that have a matching ItemResource using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Resources).
func (w publicationWhereR[Q]) HasItemResource(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := sqlite.Select(
		sm.Columns(sqlite.Raw("1")),
		sm.From(Resources.NameExpr()),
		sm.Where(Resources.Columns.ID.EQ(w.cols.ItemID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: sqlite.Exists(q)}
}
